'use strict';

const mirror = require('../web/harmony-mirror');

function arg(name, def) {
  const i = process.argv.indexOf(name);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : def;
}

(async () => {
  const report = arg('--report');
  if (report) {
    const r = await mirror.stampReport(report);
    console.log(`stamped ${r.stamped}/${r.total} dependencies as harmony_adapted in ${report}`);
    return;
  }
  const eco = arg('--ecosystem', 'python');
  const names = (arg('--names', '') || '').split(',').map((s) => s.trim()).filter(Boolean);
  const refresh = process.argv.includes('--refresh');
  const out = await mirror.statusFor(eco, names, refresh);
  console.log(JSON.stringify(out.results));
})().catch((e) => { console.error(String(e && e.message || e)); process.exit(1); });","lineStart":1,"lineEnd":29,"totalLines":29,"truncated":false}},"title":"scripts/harmony_adapted.js","time":{"start":1783559495479,"end":1783559495487}},"id":"prt_f446e1e3e001dKdh99vB1Y4H3u","sessionID":"ses_0bb93641fffePAAlpKle3oQ173","messageID":"msg_f446db4b2001gJLOOFDUn6CTlJ"}}

